"""W3C trace context: a caller's traceparent reaches ADK's spans, model calls and tool calls (generated by adk_v2/6.0.0)."""

from collections.abc import Iterator
from typing import Any

import httpx
import pytest
from google.adk.cli.utils.base_agent_loader import BaseAgentLoader
from opentelemetry import trace
from opentelemetry.sdk.trace import TracerProvider
from opentelemetry.sdk.trace.export import SimpleSpanProcessor
from opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter

import retail_kyc_onboarding.agent as agent
from retail_kyc_onboarding._engine.factories.api import HttpApiFactory
from retail_kyc_onboarding._engine.server import create_app
from retail_kyc_onboarding._engine.testing.offline import offline_providers
from retail_kyc_onboarding.workflow import WORKFLOW
from retail_kyc_onboarding.server import create_app as create_adk_app

TRACE_ID = "4bf92f3577b34da6a3ce929d0e0e4736"
TRACEPARENT = f"00-{TRACE_ID}-00f067aa0ba902b7-01"
APP = "retail_kyc_onboarding"


@pytest.fixture(scope="module")
def exporter() -> InMemorySpanExporter:
    """An in-memory span exporter on the global tracer provider (ADK traces through the global one)."""
    memory = InMemorySpanExporter()
    provider = trace.get_tracer_provider()
    if not isinstance(provider, TracerProvider):
        provider = TracerProvider()
        trace.set_tracer_provider(provider)
    provider.add_span_processor(SimpleSpanProcessor(memory))
    return memory


@pytest.fixture
def spans(exporter: InMemorySpanExporter) -> Iterator[InMemorySpanExporter]:
    exporter.clear()
    yield exporter


def traced_providers(seen: list[str | None]) -> Any:
    """Offline providers whose tools go through the real HTTP tool factory to a recording transport."""

    def handler(request: httpx.Request) -> httpx.Response:
        seen.append(request.headers.get("traceparent"))
        return httpx.Response(200, json={})

    providers = offline_providers(WORKFLOW)
    providers.api = HttpApiFactory()
    providers.api.transport = httpx.MockTransport(handler)
    return providers


def trace_ids(exporter: InMemorySpanExporter) -> set[str]:
    return {format(s.context.trace_id, "032x") for s in exporter.get_finished_spans()}


async def test_the_run_host_continues_the_callers_trace(spans: InMemorySpanExporter):
    """POST /v1/runs with a traceparent: ADK's spans, the model call spans and the tool call all carry the caller's trace id."""
    seen: list[str | None] = []
    engine = await agent.abuild_engine(providers=traced_providers(seen))
    app = create_app(engine=engine)
    async with app.router.lifespan_context(app):
        async with httpx.AsyncClient(transport=httpx.ASGITransport(app=app), base_url="http://test") as client:
            await client.post("/v1/runs", json={"message": "hello"}, headers={"traceparent": TRACEPARENT})
    assert trace_ids(spans) == {TRACE_ID}
    assert any(s.name == "call_llm" for s in spans.get_finished_spans())
    assert seen and all(t and t.split("-")[1] == TRACE_ID for t in seen)


async def test_adk_api_server_app_continues_the_callers_trace(spans: InMemorySpanExporter):
    """ADK's own API server app (/run), as server.py builds it: the same request joins the caller's trace end to end."""
    seen: list[str | None] = []
    _, offline_app = await agent.abuild(providers=traced_providers(seen))

    class Loader(BaseAgentLoader):
        def load_agent(self, agent_name: str) -> Any:
            return offline_app

        def list_agents(self) -> list[str]:
            return [APP]

    app = create_adk_app(agent_loader=Loader(), session_service_uri="memory://", use_local_storage=False)  # no file in the folder
    async with httpx.AsyncClient(transport=httpx.ASGITransport(app=app), base_url="http://test") as client:
        session = (await client.post(f"/apps/{APP}/users/u/sessions", json={})).json()["id"]
        body = {"appName": APP, "userId": "u", "sessionId": session, "newMessage": {"role": "user", "parts": [{"text": "hello"}]}}
        response = await client.post("/run", json=body, headers={"traceparent": TRACEPARENT})
    assert response.status_code == 200, response.text
    assert trace_ids(spans) == {TRACE_ID}
    assert any(s.name == "call_llm" for s in spans.get_finished_spans())
    assert seen and all(t and t.split("-")[1] == TRACE_ID for t in seen)


def test_an_oversized_tracestate_is_dropped_and_the_trace_kept():
    """opentelemetry-api 1.42.1 parses tracestate with a backtracking regex (CVE-2026-114603); past W3C's 512 characters it is not parsed."""
    from retail_kyc_onboarding._engine.trace.context import carrier_from

    assert carrier_from({"traceparent": TRACEPARENT, "tracestate": "kaya=1"}) == {"traceparent": TRACEPARENT, "tracestate": "kaya=1"}
    assert carrier_from({"traceparent": TRACEPARENT, "tracestate": "a=" + " " * 20_000 + "b"}) == {"traceparent": TRACEPARENT}
